<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><title><?= e($title) ?></title><link href="https://fonts.googleapis.com/css2?family=Syne:wght@600;700;800&family=Inter:wght@300;400;500&display=swap" rel="stylesheet"><style>:root{--ink:#0D0D0D;--paper:#F7F5F0;--cream:#EDEBE4;--accent:#C8412B;--muted:#7A7570;--white:#FFFFFF;--sidebar:240px;--ff-head:'Syne',sans-serif;--ff-body:'Inter',sans-serif;}*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}body{font-family:var(--ff-body);background:var(--paper);color:var(--ink);display:flex;min-height:100vh;}.sidebar{width:var(--sidebar);background:var(--ink);color:var(--white);display:flex;flex-direction:column;padding:1.5rem 0;position:fixed;top:0;bottom:0;left:0;z-index:50;}.sidebar-logo{font-family:var(--ff-head);font-weight:800;font-size:1.2rem;letter-spacing:-.02em;padding:0 1.5rem 2rem;}.sidebar-logo span{color:var(--accent);}.sidebar-nav{list-style:none;flex:1;}.sidebar-nav a{display:flex;align-items:center;gap:.75rem;padding:.75rem 1.5rem;font-size:.875rem;font-weight:500;color:#888;transition:all .15s;text-decoration:none;}.sidebar-nav a:hover,.sidebar-nav a.active{color:var(--white);background:rgba(255,255,255,.07);}.sidebar-footer{padding:1.5rem;border-top:1px solid #222;}.sidebar-user{font-size:.8rem;color:#666;margin-bottom:.75rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}.sidebar-logout{display:block;font-size:.8rem;color:#888;text-decoration:none;}.main{margin-left:var(--sidebar);flex:1;padding:2.5rem;}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:2.5rem;}.topbar h1{font-family:var(--ff-head);font-size:1.5rem;font-weight:800;}.card{background:var(--white);border:1px solid var(--cream);border-radius:10px;padding:1.5rem;margin-bottom:1.5rem;}.card h2{font-family:var(--ff-head);font-weight:700;font-size:1rem;margin-bottom:1rem;}.table{width:100%;border-collapse:collapse;}.table th{font-size:.72rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);padding:.6rem 0;border-bottom:1px solid var(--cream);text-align:left;}.table td{padding:.85rem 0;border-bottom:1px solid var(--cream);font-size:.875rem;}</style></head><body><aside class="sidebar"><div class="sidebar-logo">creative<span>.</span></div><ul class="sidebar-nav"><li><a href="<?= APP_URL ?>/admin">📊 Dashboard</a></li><li><a href="<?= APP_URL ?>/admin/orders">📋 Pesanan</a></li><li><a href="<?= APP_URL ?>/admin/services" class="active">◈ Layanan</a></li><li><a href="<?= APP_URL ?>/admin/portfolio">◆ Portfolio</a></li></ul><div class="sidebar-footer"><div class="sidebar-user"><?= e(Session::get('user_name')) ?></div><a href="<?= APP_URL ?>/logout" class="sidebar-logout">← Keluar</a></div></aside><main class="main"><div class="topbar"><h1><?= e($title) ?></h1></div><div class="card"><h2>Daftar Layanan</h2><table class="table"><thead><tr><th>Nama</th><th>Kategori</th><th>Harga</th><th>Status</th><th>Pesanan</th></tr></thead><tbody><?php if (empty($services)): ?><tr><td colspan="5" style="text-align:center;padding:2rem;color:var(--muted);">Tidak ada layanan</td></tr><?php else: ?><?php foreach ($services as $s): ?><tr><td><strong><?= e($s['name']) ?></strong></td><td><?= e($s['category_name'] ?? '-') ?></td><td><?= formatRupiah((float)$s['price']) ?></td><td><?= $s['is_active'] ? '✓ Aktif' : '✗ Nonaktif' ?></td><td><?= (int)$s['order_count'] ?></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></main></body></html>